import os,glob,re
import json

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])   
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()

demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

# Extract all non-zero values with their counts
nonzero_vals = []
for r in range(9):
    for c in range(9):
        val = demo_in[r][c]
        if val > 0:
            nonzero_vals.append(val)

print(f"All non-zero values ({len(nonzero_vals)}): {nonzero_vals}")

# Analyze output structure
print("\n=== OUTPUT CELL VALUES ===")
out_rows = {}
out_cols = {}
for r in range(3):
    for c in range(6):
        out_rows[r] = out_rows.get(r, []) + [demo_out[r][c]]
        out_cols[c] = out_cols.get(c, []) + [demo_out[r][c]]

print("Rows:")
for r in range(3):
    print(f"  Row {r}: {[demo_out[r][c] for c in range(6)]}, count={sum(1 for v in out_rows[r] if v==8)}")
print("Cols:")
for c in range(6):
    print(f"  Col {c}: {[demo_out[r][c] for r in range(3)]}, count={sum(1 for v in out_cols[c] if v==8)}")

# Check: is output just listing all 8s followed by all 4s?
eight_count = sum(v==8 for v in nonzero_vals)
four_count = sum(v==4 for v in nonzero_vals)
print(f"\n8 count in input: {eight_count}")
print(f"4 count in input: {four_count}")

# Look for a pattern in how values are placed
print("\n=== VALUE DISTRIBUTION IN OUTPUT ===")
val_counts = {}
for r in range(3):
    for c in range(6):
        v = demo_out[r][c]
        val_counts[v] = val_counts.get(v, 0) + 1
print(f"Value counts: {val_counts}")
